func startSignalChild(t *testing.T, command string, graceful bool) (*exec.Cmd, *bufio.Reader) {
	t.Helper()
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
	t.Cleanup(cancel)
	child := exec.CommandContext(ctx, executable, "-test.run=^TestCommandSignalChild$")
	child.Env = append(os.Environ(), "TS_ORCH_SIGNAL_TEST_COMMAND="+command,
		fmt.Sprintf("TS_ORCH_SIGNAL_TEST_GRACEFUL=%t", graceful))
	child.Stderr = os.Stderr
	input, err := child.StdinPipe()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = input.Close() })
	output, err := child.StdoutPipe()
	if err != nil {
		t.Fatal(err)
	}
	if err := child.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if child.ProcessState == nil {
			_ = child.Process.Kill()
			_ = child.Wait()
		}
	})
	return child, bufio.NewReader(output)
}

func expectSignalChildOutput(t *testing.T, output *bufio.Reader, want string) {
	t.Helper()
	line, err := output.ReadString('\n')
	if err != nil || line != want+"\n" {
		t.Fatalf("child output = %q, error = %v; want %q", line, err, want)
	}
}

func expectSignalExit(t *testing.T, child *exec.Cmd, want syscall.Signal) {
	t.Helper()
	err := child.Wait()
	exit, ok := errors.AsType[*exec.ExitError](err)
	if !ok {
		t.Fatalf("child exit = %v, want termination by %s", err, want)
	}
	status, ok := exit.Sys().(syscall.WaitStatus)
	if !ok || !status.Signaled() || status.Signal() != want {
		t.Fatalf("child exit = %v, want termination by %s", err, want)
	}
}

func commandContext(args []string) (context.Context, context.CancelFunc) {
	parent := context.Background()
	if len(args) > 0 && (args[0] == "bootstrap" || args[0] == "release") {
		// Operator commands initialize OCI credentials synchronously. Retain
		// default signal termination because that work cannot observe cancellation.
		return parent, func() {}
	}

	signalContext, stopSignals := signal.NotifyContext(parent, os.Interrupt, syscall.SIGTERM)
	ctx, cancel := context.WithCancel(parent)
	stopForwarding := context.AfterFunc(signalContext, func() {
		// Restore default termination before the runtime starts graceful shutdown,
		// so a second signal can stop a runtime whose cleanup is stuck.
		stopSignals()
		cancel()
	})
	return ctx, func() {
		stopForwarding()
		stopSignals()
		cancel()
	}
}

