// Invoke is the same native API used by the command dispatcher, with optional injected dependencies.
func (e *Engine) Invoke(name string, args []any, kwargs Object) (any, error) {
	return capture(func() any { return e.invoke(name, args, kwargs) })
}
func (e *Engine) invoke(name string, args []any, kw Object) any {
	arg := func(i int) any {
		if i < len(args) {
			return args[i]
		}
		return nil
	}
	option := func(i int, key string, fallback any) any {
		if i < len(args) {
			return args[i]
		}
		if v, ok := kw[key]; ok {
			return v
		}
		return fallback
	}
	now := e.now()
	if t, ok := option(3, "now", nil).(time.Time); ok {
		now = t
	}
	switch name {
	case "main":
		e.run(e.Argv[1:])
		return nil
	case "load_plan":
		path := pathValue(option(0, "path", Path(e.PlanPath)))
		return e.loadPlan(path)
	case "require_ocid":
		return requireOCID(arg(0), str(arg(1)), text(option(2, "region", "")))
	case "oci":
		return e.realOCI(args, kw)
	case "checked_tool":
		return e.realChecked(args)
	case "collect_scoped_images":
		return e.scopedImages(arg(0), arg(1))
	case "collect_inventory":
		return e.collectInventory(obj(arg(0)))
	case "import_inventory":
		return e.importInventory(obj(arg(0)), pathValue(arg(1)), pathValue(arg(2)), pathValue(arg(3)))
	case "estimate":
		age := number(option(4, "max_age_minutes", 15))
		return e.estimate(obj(arg(0)), obj(arg(1)), pathValue(option(2, "plan_path", nil)), now, age)

func (e *Engine) run(argv []string) {
	if len(argv) == 0 {
		fail("OCI preview requires a command")
	}
	command := argv[0]
	f := flag.NewFlagSet("oci-preview", flag.ContinueOnError)
	f.SetOutput(io.Discard)
	args := Object{}
	root := filepath.Dir(e.PlanPath)
	if e.PlanPath == "" {
		e.PlanPath = "deploy/oci-region/plan.json"
		root = "deploy/oci-region"
	}
	defaults := map[string]string{"plan": e.PlanPath, "inventory": filepath.Join(root, "inventory.json"), "admission": filepath.Join(root, "admission.json")}
	for _, name := range []string{"plan", "inventory", "out", "admission", "pair-intent", "left-plan", "left-inventory", "left-admission", "right-plan", "right-inventory", "right-admission", "bootstrap-tool", "anchor", "manifest", "identity", "image-ocid", "release-tool", "image-receipt", "release-delegation", "release-root", "image-file", "base-image-file", "kernel-file", "owner-ssh-public-key", "reviewed-plan", "host-enrollment", "managed-host-image-receipt", "managed-host-image-delegation", "slot", "profile", "projection", "phase", "staged-versions", "imported-images", "previous-admission", "previous-projection", "previous-inventory", "previous-imported-images", "previous-staged-versions"} {
		args[strings.ReplaceAll(name, "-", "_")] = defaults[name]
		f.Func(name, "", func(v string) error { args[strings.ReplaceAll(name, "-", "_")] = v; return nil })
	}
	args["bootstrap_root"] = []any{}
	f.Func("bootstrap-root", "", func(v string) error {
		args["bootstrap_root"] = append(arr(args["bootstrap_root"]), Path(v))
		return nil
	})
	if err := f.Parse(argv[1:]); err != nil {
		panic(err)
	}
	if f.NArg() > 0 {
		fail("unexpected OCI preview arguments")
	}
	get := func(k string) string { return text(args[k]) }
	require := func(message string, names ...string) {
		for _, k := range names {
			if !truth(args[k]) {
				fail(message)
			}
		}
	}
	path := get("plan")
	if command == "inspect-private-peer" {
		require("private peer inspection requires pair intent, both regional plans, inventories, admissions, and --out", "pair_intent", "left_plan", "left_inventory", "left_admission", "right_plan", "right_inventory", "right_admission", "out")
		result := e.inspectPrivatePeer([]string{get("pair_intent"), get("left_plan"), get("left_inventory"), get("left_admission"), get("right_plan"), get("right_inventory"), get("right_admission")})
		writeJSON(get("out"), result)
		if e.Stdout != nil {
			fmt.Fprintf(e.Stdout, "private peer configuration readback PASS cells=%s budget_admission=%s\n", strings.Join(keys(obj(result["cells"])), ","), strings.ToUpper(text(obj(result["budget_admission"])["status"])))
		}
		return
	}

if command == "import-inventory" {
	snapshot := e.importInventory(plan, get("projection"), get("staged_versions"), get("previous_projection"))
	e.verifyImportInventory(plan, snapshot, must(filepath.Abs(path)), e.now(), 15)
	out := get("out")
	if out == "" {
		out = get("inventory")
	}
	writeJSON(out, snapshot)
	if e.Stdout != nil {
		fmt.Fprintf(e.Stdout, "captured %d scoped images and %d detailed buckets\n", len(arr(snapshot["images"])), len(arr(snapshot["buckets"])))
	}
	return
}
if command == "inspect-foundation" {
	require("foundation inspection requires --out", "out")
	result := e.inspectFoundation(plan, must(filepath.Abs(path)), get("inventory"), get("admission"))
	writeJSON(get("out"), result)
	if e.Stdout != nil {
		fmt.Fprintf(e.Stdout, "foundation readback PASS region=%s inventory=%s\n", str(plan["region"]), str(result["inventory_sha256"]))
	}
	return
}
if command == "import-admit" || command == "import-reconcile" {
	require("import admission requires --projection and --out", "projection", "out")
	phase := get("phase")
	if command == "import-reconcile" {
		phase = "post-import"
	}
	if phase == "" {
		fail("import-admit requires --phase")
	}
	inventory := readJSON(get("inventory"), 4*1024*1024, "manual region import inventory")
	imports := reviewedImports(plan, inventory, get("projection"))
	var lineage Object
	full := sameRoles(keys(imports), "base", "final")
	if full {
		if get("previous_projection") != "" {
			if phase != "pre-stage" || get("staged_versions") != "" || get("previous_admission") == "" || get("previous_inventory") == "" || get("previous_staged_versions") == "" || get("previous_imported_images") == "" {
				fail("base-only lineage requires the first full pre-stage admission and all prior evidence")
			}
			lineage = e.establishLineage(plan, get("projection"), get("previous_projection"), get("previous_inventory"), get("previous_admission"), get("previous_staged_versions"), get("previous_imported_images"), must(filepath.Abs(path)))
		} else if get("previous_admission") != "" {

			if get("previous_staged_versions") == "" {
				fail("pre-import requires the preceding base object version receipt")
			}
			if previous["staged_versions_sha256"] != fileSHA(get("previous_staged_versions")) {
				fail("preceding base object receipt changed")
			}
			base, current := importReceipt(get("previous_staged_versions"), "versions", fileSHA(get("projection")), []string{"base"}), importReceipt(get("staged_versions"), "versions", fileSHA(get("projection")), keys(imports))
			if base["base"] != current["base"] {
				fail("staged receipt changed the admitted base object version")
			}
		}
		if phase == "pre-import" && get("imported_images") != "" && previous["imported_images_sha256"] != nil {
			fail("base readback requires the preceding two-maximum pre-import admission")
		}
		if phase == "post-import" {
			if !full {
				if get("previous_imported_images") == "" || !truth(previous["imported_images_sha256"]) {
					fail("base reconciliation requires the preceding image readback admission and receipt")
				}
				if fileSHA(get("previous_imported_images")) != previous["imported_images_sha256"] {
					fail("preceding base image receipt changed")
				}
				base, final := importReceipt(get("previous_imported_images"), "images", fileSHA(get("projection")), []string{"base"}), importReceipt(get("imported_images"), "images", fileSHA(get("projection")), []string{"base"})
				if base["base"] != final["base"] {
					fail("final image receipt changed the admitted base image OCID")
				}
			} else if lineage == nil {
				fail("final reconciliation lacks the carried base image readback")
			}
		}
	}
	if full && lineage == nil {
		fail("full import admission lacks the carried base-only lineage")
	}
	result := e.importEstimate(plan, inventory, get("projection"), phase, get("staged_versions"), get("imported_images"), must(filepath.Abs(path)), e.now(), 15, lineage)
	now := e.now()
	optionalSHA := func(k string) any {
		if get(k) == "" {
			return nil
		}
		return fileSHA(get(k))
	}
	admission := Object{"schema_version": 3, "phase": phase, "admitted_at": pythonTime(now), "expires_at": pythonTime(now.Add(15 * time.Minute)), "plan_sha256": fileSHA(path), "inventory_sha256": fileSHA(get("inventory")), "projection_sha256": fileSHA(get("projection")), "staged_versions_sha256": optionalSHA("staged_versions"), "imported_images_sha256": optionalSHA("imported_images"), "previous_admission_sha256": optionalSHA("previous_admission"), "base_lineage": lineage, "estimate": result}
	writeJSON(get("out"), admission)
	e.print(admission)
	return
}

func fileSHA(path string) string {
	wire := must(os.ReadFile(path))
	h := sha256.Sum256(wire)
	return hex.EncodeToString(h[:])
}
func wireSHA(wire []byte) string { h := sha256.Sum256(wire); return hex.EncodeToString(h[:]) }
func readBytes(path string, limit int, label string) []byte {
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if err != nil {
		fail(label + " is unreadable or invalid JSON")
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		fail(label + " is unreadable or invalid JSON")
	}
	if !st.Mode().IsRegular() || st.Size() <= 0 || st.Size() > int64(limit) {
		fail(label + " has invalid size or is not a regular file")
	}
	wire := must(io.ReadAll(io.LimitReader(f, int64(limit+1))))
	if len(wire) == 0 || len(wire) > limit {
		fail(label + " has invalid size")
	}
	return wire
}
func readJSON(path string, limit int, label string) Object {
	wire := readBytes(path, limit, label)
	v, err := decodeJSON(wire)
	if err != nil {
		if strings.Contains(err.Error(), "duplicate") {
			fail("JSON document has duplicate fields")
		}
		fail(label + " is unreadable or invalid JSON")
	}
	m, ok := v.(map[string]any)
	if !ok {
		fail(label + " must be an object")
	}
	return m
}

func (e *Engine) call(name string, args []any, kwargs Object) any {
	if e.Dependency != nil && (name == "oci" || name == "checked_tool" || name == "subprocess.run" || name == "cloudflare_origin_ips" || e.Overrides[name]) {
		v, err := e.Dependency(name, args, kwargs)
		if err != nil {
			panic(err)
		}
		return v
	}
	return e.invoke(name, args, kwargs)
}
func (e *Engine) oci(region string, args ...string) any {
	a := make([]any, len(args))
	for i, x := range args {
		a[i] = x
	}
	kw := Object{}
	if region != "" {
		kw["region"] = region
	}

import_production.text:
func (e *Engine) importInventory(plan Object, projection, staged, previous string) Object {
	snapshot := obj(e.call("collect_inventory", []any{plan}, Object{}))
	namespace := e.oci(text(plan["region"]), "os", "ns", "get")
	if text(namespace) == "" {
		fail("object namespace is missing")
	}
	buckets := arr(snapshot["buckets"])
	results := make([][]any, len(buckets))
	for i, v := range buckets {
		b := obj(v)
		cmd := "list"
		if b["versioning"] == "Enabled" {
			cmd = "list-object-versions"
		}
		results[i] = rows(e.oci(text(b["region"]), "os", "object", cmd, "--namespace-name", str(namespace), "--bucket-name", str(b["name"]), "--fields", "name,size,storageTier,archivalState", "--all"))
	}
	for i, v := range buckets {
		b := obj(v)
		versions := []any{}
		total := 0.0
		for _, x := range results[i] {
			r := objectVersion(obj(x), b["versioning"] == "Enabled")
			versions = append(versions, r)
			if !truth(r["is_delete_marker"]) {
				total += number(r["size"])
			}
		}
		b["versions"] = versions
		b["object_count"] = len(versions)
		b["bytes"] = total
	}
	snapshot["schema_version"] = 3
	snapshot["object_namespace"] = namespace
	snapshot["current_objects"] = []any{}
	if staged != "" {
		if projection == "" {
			fail("current object HEAD requires the reviewed import projection")
		}
		imports := reviewedImports(plan, snapshot, projection)
		receipt := readJSON(staged, 64*1024, "staged object version receipt")
		roles := keys(obj(receipt["versions"]))
		if !sameRoles(roles, "base") && !sameRoles(roles, "base", "final") {
			fail("current object HEAD requires base or both staged version IDs")
		}
		hash := fileSHA(projection)
		if previous != "" && sameRoles(roles, "base") {
			old := reviewedImports(plan, snapshot, previous)
			if !sameRoles(keys(old), "base") || !sameRoles(keys(imports), "base", "final") || !eq(old["base"], imports["base"]) {
				fail("full import projection base row differs from the staged base-only projection")
			}
			hash = fileSHA(previous)
		}
		versions := importReceipt(staged, "versions", hash, roles)
		current := []any{}
		for _, role := range keys(versions) {
			entry := obj(imports[role])
			ref := obj(entry["object"])
			current = append(current, e.call("current_object_head", []any{namespace, ref["bucket"], ref["key"], plan["region"]}, Object{}))
		}
		snapshot["current_objects"] = current
	}
	return snapshot
}

func importReceipt(path, field, hash string, roles []string) Object {
	r := readJSON(path, 64*1024, "import "+field+" receipt")
	values := obj(r[field])
	valid := eq(r["schema_version"], 1) && r["projection_sha256"] == hash && sameRoles(keys(values), roles...)
	seen := map[string]bool{}
	for _, v := range values {
		if text(v) == "" || seen[text(v)] {
			valid = false
		}
		seen[text(v)] = true
	}
	if !valid {
		fail("import " + field + " receipt is incomplete or bound to another projection")
	}
	if field == "images" {
		for _, v := range values {
			if !strings.HasPrefix(text(v), "ocid1.image.") {
				fail("import image receipt lacks OCI image OCIDs")
			}
		}
	}
	return values
}
func (e *Engine) previousAdmission(path, phase, projection, planPath, staged, imported string) Object {
	p := readJSON(path, 64*1024, "previous import admission")
	_, estimate := p["estimate"].(Object)
	if !eq(p["schema_version"], 3) || p["phase"] != phase || p["plan_sha256"] != fileSHA(planPath) || p["projection_sha256"] != projection || (staged != "" && p["staged_versions_sha256"] != staged) || (imported != "" && p["imported_images_sha256"] != imported) || !estimate {
		fail("previous import admission does not bind this projection and stage")
	}
	admitted, aok := parseTime(p["admitted_at"])
	expires, eok := parseTime(p["expires_at"])
	if !aok || !eok || !expires.After(admitted) || expires.After(admitted.Add(15*time.Minute+30*time.Second)) || admitted.After(e.now().Add(30*time.Second)) {
		fail("previous import admission has invalid timestamps")
	}
	return p
}

func (e *Engine) establishLineage(plan Object, full, base, inventoryPath, admission, staged, images, planPath string) Object {
	inventory := readJSON(inventoryPath, 4*1024*1024, "base-only import inventory")
	f, b := reviewedImports(plan, inventory, full), reviewedImports(plan, inventory, base)
	if !sameRoles(keys(b), "base") || !sameRoles(keys(f), "base", "final") || !eq(b["base"], f["base"]) {
		fail("full import projection base row differs from the admitted base-only input")
	}
	previous := e.previousAdmission(admission, "pre-import", fileSHA(base), planPath, fileSHA(staged), fileSHA(images))
	if previous["inventory_sha256"] != fileSHA(inventoryPath) {
		fail("base-only admission does not bind the supplied inventory")
	}
	at, _ := parseTime(previous["admitted_at"])
	_, offset := at.Zone()
	if offset != 0 {
		fail("base-only admission timestamp is not UTC")
	}
	expected := e.importEstimate(plan, inventory, base, "pre-import", staged, images, planPath, at, 10*365*24*60, nil)
	if !eq(previous["estimate"], expected) {
		fail("base-only admission cost differs from its exact inventory and receipts")
	}
	versions, imported := importReceipt(staged, "versions", fileSHA(base), []string{"base"}), importReceipt(images, "images", fileSHA(base), []string{"base"})
	return carriedLineage(Object{"schema_version": 1, "plan_sha256": fileSHA(planPath), "projection_sha256": fileSHA(base), "admission_sha256": fileSHA(admission), "inventory_sha256": fileSHA(inventoryPath), "staged_versions_sha256": fileSHA(staged), "imported_images_sha256": fileSHA(images), "base_version_id": versions["base"], "base_image_id": imported["base"], "estimate": expected}, fileSHA(planPath))
}

